import {STORAGE_KEY,statuses,escapeHTML as esc,isLate,isToday,nextNumber,validOrders,toCSV,getServices,serviceLabel,validateWork,bagOptions} from './domain.js';
const $=s=>document.querySelector(s);let orders=[],demoOrders=[],demo=false,view='board',filter='all',editing=null,pendingAction=null,recognition=null,toastTimer,storageBlocked=false;
try{const raw=localStorage.getItem(STORAGE_KEY);if(raw){const data=JSON.parse(raw);if(!validOrders(data))throw Error('invalid');orders=data;}}catch{storageBlocked=true;}
const current=()=>demo?demoOrders:orders;
const pad=n=>String(n).padStart(2,'0');const dateInput=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const number=o=>String(o.number).padStart(3,'0');
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,6500);}
function persist(next){if(demo){demoOrders=next;return true;}if(storageBlocked){toast('No se puede guardar. Exporta tus registros y revisa el almacenamiento del navegador.');return false;}try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||'[]');if(!validOrders(saved)||JSON.stringify(saved)!==JSON.stringify(orders)){if(validOrders(saved))orders=saved;render();toast('El cuaderno cambió en otra pestaña. Revisa los datos y vuelve a intentarlo.');return false;}localStorage.setItem(STORAGE_KEY,JSON.stringify(next));orders=next;return true;}catch{toast('No se pudo guardar. Conservamos los datos anteriores; exporta una copia.');return false;}}
function dueLabel(o){const d=new Date(o.due),now=new Date(),tomorrow=new Date();tomorrow.setDate(now.getDate()+1);const day=isToday(o)?'Hoy':d.toDateString()===tomorrow.toDateString()?'Mañana':d.toLocaleDateString('es-EC',{day:'numeric',month:'short',...(d.getFullYear()!==now.getFullYear()?{year:'numeric'}:{})});return `${day}, ${d.toLocaleTimeString('es-EC',{hour:'2-digit',minute:'2-digit',hour12:false})}`;}
function urgency(o){if(o.status==='delivered')return '';if(isLate(o))return '<span class="due-pill late">Retiro vencido</span>';if(new Date(o.due)-new Date()<2*3600000)return '<span class="due-pill soon">Retiro próximo</span>';return '';}
function workDetails(o){const entries=[];if(o.roast)entries.push(['Tueste',o.roast]);if(o.grind)entries.push(['Molienda',o.grind]);if(o.packaging){entries.push(['Funda',o.packaging.bagType]);if(o.packaging.gramsPerBag)entries.push(['Peso por funda',`${o.packaging.gramsPerBag} g${o.packaging.gramsPerBag===1000?' · 1 kg':''}`]);if(o.packaging.presentation)entries.push(['Indicaciones',o.packaging.presentation]);}return entries.length?`<dl class="work-details">${entries.map(([label,value])=>`<div><dt>${label}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>`:'';}
function chosenServices(){return [...document.querySelectorAll('[name="services"]:checked')].map(el=>el.value);}
function updateServiceFields(){const selected=chosenServices();for(const [service,group] of [['Tostar','roast-fields'],['Moler','grind-fields'],['Empaquetar','packaging-fields']]){const enabled=selected.includes(service);$('#'+group).hidden=!enabled;$('#'+group).querySelectorAll('input,select,button').forEach(input=>input.disabled=!enabled);}$('#bag-type').required=selected.includes('Empaquetar');$('#grams-per-bag').required=selected.includes('Empaquetar');updateCustomBag();}
function updateCustomBag(){const custom=chosenServices().includes('Empaquetar')&&$('#bag-type').value==='other';$('#custom-bag-field').hidden=!custom;$('#custom-bag').disabled=!custom;$('#custom-bag').required=custom;}
$('#bag-type').addEventListener('change',updateCustomBag);
document.querySelectorAll('[data-grams]').forEach(button=>button.addEventListener('click',()=>{$('#grams-per-bag').value=button.dataset.grams;$('#grams-per-bag').focus();}));
document.querySelectorAll('[name="services"]').forEach(el=>el.addEventListener('change',()=>{updateServiceFields();$('#form-error').textContent='';}));
function card(o,tv=false){return `<article class="order-card"><div class="card-content"><div class="card-top"><span class="order-number">#${number(o)}</span><span class="status-badge ${o.status}">${statuses[o.status]}</span></div><h3>${esc(o.client)}</h3><div class="service-line"><b>${esc(o.service)}</b>${o.weight?`<span>· ${esc(o.weight)} kg recibidos</span>`:''}</div>${workDetails(o)}${o.instructions?`<p class="instructions">${esc(o.instructions)}</p>`:''}<div class="card-due"><span>◷ ${dueLabel(o)}</span>${urgency(o)}</div></div>${tv?'':`<div class="card-footer"><button class="edit-order" data-edit="${esc(o.id)}">Ver / editar</button>${o.status==='delivered'?'<span class="delivered-label">✓ Retirado por el cliente</span>':`<button class="next-status" data-next="${esc(o.id)}">${o.status==='pending'?'Marcar listo para retirar':'Marcar entregado'} →</button>`}</div>`}</article>`;}
function render(){const data=current(),active=data.filter(o=>o.status!=='delivered');$('#stat-pending').textContent=active.filter(o=>o.status==='pending').length;$('#stat-today').textContent=active.filter(o=>isToday(o)).length;$('#stat-ready').textContent=active.filter(o=>o.status==='ready').length;$('#stat-late').textContent=active.filter(o=>isLate(o)).length;$('#nav-count').textContent=active.length;$('#tab-all').textContent=view==='history'?data.filter(o=>o.status==='delivered').length:active.length;$('#demo-banner').hidden=!demo;$('#demo-button').textContent=demo?'Salir del ejemplo':'Ver ejemplo';$('#footer-note').textContent=demo?'Modo de ejemplo · Los cambios no se guardan.':'Recordatorios mientras esta página esté abierta.';
$('#mobile-history').textContent=view==='history'?'Cuaderno':'Historial';const search=$('#search').value.trim().toLocaleLowerCase('es');let visible=data.filter(o=>view==='history'?o.status==='delivered':o.status!=='delivered').filter(o=>(filter==='all'||(filter==='late'?isLate(o):o.status===filter))&&(!search||`${o.client} ${number(o)} ${o.service} ${o.instructions} ${o.roast??''} ${o.grind??''} ${o.packaging?.bagType??''} ${o.packaging?.gramsPerBag??''} ${o.packaging?.presentation??''}`.toLocaleLowerCase('es').includes(search))).sort((a,b)=>view==='history'?new Date(b.deliveredAt)-new Date(a.deliveredAt):new Date(a.due)-new Date(b.due));$('#list-count').textContent=visible.length;$('#orders-grid').innerHTML=visible.map(o=>card(o)).join('');$('#empty-state').hidden=visible.length>0;const filtered=!!search||filter!=='all';$('#empty-title').textContent=filtered?'No encontramos pedidos con ese filtro.':view==='history'?'Aquí quedarán los trabajos entregados.':'Aquí empieza un trabajo más organizado.';$('#empty-description').textContent=filtered?'Prueba otro nombre, número o estado.':view==='history'?'Al confirmar una entrega, el pedido pasa a este historial.':'Registra el primer pedido con sus instrucciones y fecha de retiro.';$('#empty-add').hidden=filtered||view==='history';$('#page-title').textContent=view==='history'?'Cada trabajo tiene su historia.':'Cada pedido, en su lugar.';$('#page-subtitle').textContent=view==='history'?'Consulta los trabajos que ya retiraron tus clientes.':'Del saco al retiro. Un cuaderno compartido con tu pantalla.';$('#breadcrumb-view').textContent=view==='history'?'Historial':'Cuaderno de pedidos';$('#list-title').firstChild.textContent=view==='history'?'Trabajos entregados ':'Cuaderno de pedidos ';$('#list-description').textContent=view==='history'?'Las últimas entregas aparecen primero.':'Los próximos retiros aparecen primero.';$('.tabs').hidden=view==='history';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));
const tv=active.sort((a,b)=>new Date(a.due)-new Date(b.due));$('#tv-grid').innerHTML=tv.length?tv.map(o=>card(o,true)).join(''):'<h2>No hay pedidos pendientes. Todo al día.</h2>';$('#tv-summary').textContent=`${tv.length} trabajos activos · ${tv.filter(o=>isLate(o)).length} con retiro vencido`;$('#tv-demo').textContent=demo?'DATOS DE EJEMPLO':'';}
function openOrder(id=null,voice=false){stopVoice();editing=id;$('#order-form').reset();$('#transcript-container').hidden=true;$('#transcript').value='';$('#form-error').textContent='';$('#voice-status').textContent='Revisa siempre los datos antes de confirmar.';const o=id?current().find(x=>x.id===id):null;$('#dialog-title').textContent=o?`Pedido #${number(o)}`:'Nuevo pedido';if(o){$('#client').value=o.client;document.querySelectorAll('[name="services"]').forEach(el=>el.checked=getServices(o).includes(el.value));$('#roast').value=o.roast??'';$('#grind').value=o.grind??'';const bag=o.packaging?.bagType??'';$('#bag-type').value=bagOptions.includes(bag)?bag:bag?'other':'';$('#custom-bag').value=bagOptions.includes(bag)?'':bag;$('#grams-per-bag').value=o.packaging?.gramsPerBag??'';$('#presentation').value=o.packaging?.presentation??'';$('#weight').value=o.weight??'';$('#instructions').value=o.instructions;$('#due-date').value=o.due.slice(0,10);$('#due-time').value=o.due.slice(11,16);}else{$('#due-date').value=dateInput(new Date());$('#due-time').value='17:00';}updateServiceFields();$('#order-dialog').showModal();if(voice)$('#voice-status').textContent='Pulsa «Dictar» y permite el micrófono. Luego revisa y completa los campos.';}
function closeOrder(){stopVoice();$('#order-dialog').close();}
function reviewRows(o){return `<div class="review-row"><span>Cliente</span><b>${esc(o.client)}</b></div><div class="review-row"><span>Servicios</span><b>${esc(o.service)}</b></div><div class="review-row"><span>Peso total recibido</span><b>${o.weight?esc(o.weight)+' kg':'Sin registrar'}</b></div>${workDetails(o)}<div class="review-row"><span>Retiro</span><b>${dueLabel(o)}</b></div><div class="review-row"><span>Otras instrucciones</span><b>${esc(o.instructions)||'Sin indicaciones adicionales'}</b></div>`;}
function showConfirm(title,body,label,action){$('#confirm-title').textContent=title;$('#confirm-body').innerHTML=body;$('#confirm-save').textContent=label;pendingAction=action;$('#confirm-dialog').showModal();}
$('#order-form').addEventListener('submit',e=>{e.preventDefault();stopVoice();const client=$('#client').value.trim(),instructions=$('#instructions').value.trim(),due=`${$('#due-date').value}T${$('#due-time').value}`;if(!client||!Number.isFinite(Date.parse(due))){$('#form-error').textContent='Completa el cliente y una fecha de retiro válida.';return;}const services=chosenServices(),weight=Number($('#weight').value),packaging=services.includes('Empaquetar')?{bagType:$('#bag-type').value==='other'?$('#custom-bag').value.trim():$('#bag-type').value,gramsPerBag:Number($('#grams-per-bag').value),presentation:$('#presentation').value.trim()}:null;const error=validateWork({weight,services,packaging,instructions});if(error){$('#form-error').textContent=error;return;}const original=editing?current().find(o=>o.id===editing):null;if(editing&&!original){toast('Este pedido cambió. Cierra el formulario y vuelve a abrirlo.');return;}const o={...(original||{id:crypto.randomUUID(),number:nextNumber(current()),createdAt:new Date().toISOString(),status:'pending'}),client,services,service:serviceLabel(services),weight,packaging,roast:services.includes('Tostar')?$('#roast').value.trim():'',grind:services.includes('Moler')?$('#grind').value.trim():'',instructions,due};showConfirm(original?'Confirmar cambios':'¿Está correcto el pedido?',reviewRows(o)+(isLate(o)?'<div class="form-note">La fecha de retiro ya pasó. El pedido aparecerá como vencido.</div>':''),'Confirmar y guardar',()=>{const changed=original?current().map(x=>x.id===o.id?o:x):[...current(),o];if(!persist(changed))return false;closeOrder();render();toast(`Pedido #${number(o)} guardado. Anota el número junto al nombre en la cinta.`);return true;});});
$('#confirm-save').onclick=()=>{if(pendingAction?.()!==false){$('#confirm-dialog').close();pendingAction=null;}};const closeConfirm=()=>{$('#confirm-dialog').close();pendingAction=null;};$('#confirm-back').onclick=closeConfirm;$('#confirm-close').onclick=closeConfirm;
$('#orders-grid').onclick=e=>{const edit=e.target.closest('[data-edit]');if(edit){openOrder(edit.dataset.edit);return;}const next=e.target.closest('[data-next]');if(!next)return;const o=current().find(x=>x.id===next.dataset.next);if(!o)return;const status=o.status==='pending'?'ready':'delivered';showConfirm(status==='ready'?'¿Terminó el proceso?':'¿El cliente retiró el café?',`<p><b>#${number(o)} · ${esc(o.client)}</b></p><p>${esc(o.service)}</p><div class="form-note">${status==='ready'?'El trabajo estará terminado, incluido el empaque si fue solicitado. Quedará listo para que el cliente lo retire.':'Confirma únicamente cuando el café haya sido entregado. El pedido pasará al historial.'}</div>`,status==='ready'?'Confirmar: listo para retirar':'Confirmar entrega',()=>{const latest=current().find(x=>x.id===o.id);if(!latest||latest.status!==o.status){toast('El estado cambió. Revisa el pedido.');render();return false;}if(!persist(current().map(x=>x.id===o.id?{...x,status,[status==='ready'?'readyAt':'deliveredAt']:new Date().toISOString()}:x)))return false;render();toast(status==='ready'?'Trabajo terminado y listo para que el cliente lo retire.':'Entrega registrada. Puedes consultar el pedido en el historial.');return true;});};
document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=closeOrder);$('#order-dialog').addEventListener('cancel',stopVoice);$('#new-order').onclick=()=>openOrder();$('#empty-add').onclick=()=>openOrder();$('#voice-order').onclick=()=>openOrder(null,true);$('#mobile-history').onclick=()=>{view=view==='history'?'board':'history';filter='all';$('#search').value='';render();};$('#search').oninput=render;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;filter='all';$('#search').value='';render();});$('.brand').onclick=e=>{e.preventDefault();view='board';filter='all';$('#search').value='';render();};
function startDemo(){demo=true;const now=new Date();const due=(days,h,m=0)=>{const d=new Date(now);d.setDate(now.getDate()+days);return `${dateInput(d)}T${pad(h)}:${pad(m)}`;};demoOrders=[{client:'María Pérez',service:'Tostar y moler',roast:'Medio',grind:'Fina',weight:10,instructions:'Tueste medio. Dejar enfriar y moler fino.',due:due(0,Math.max(0,now.getHours()-1)),status:'pending'},{client:'Cafetería La Esquina',services:['Moler','Empaquetar'],service:'Moler + Empaquetar',grind:'Media para filtro',packaging:{bagType:'Negra de libra',gramsPerBag:400,presentation:'Conservar el nombre del cliente en cada funda'},weight:8,instructions:'Molienda media para cafetera de filtro. Mantener separado.',due:due(0,23,30),status:'pending'},{client:'Don Alberto',service:'Tostar',weight:25,instructions:'Tueste oscuro. Entregar en el saco del cliente.',due:due(1,9),status:'ready'},{client:'Ana Zambrano',service:'Tostar y moler',weight:12.5,instructions:'Tueste claro y molienda gruesa para prensa francesa.',due:due(1,15),status:'pending'},{client:'Luis Andrade',service:'Moler',weight:5,instructions:'Molienda fina. Dos botes identificados con su nombre.',due:due(2,10),status:'ready'},{client:'Cooperativa El Bosque',service:'Tostar',weight:40,instructions:'Tueste medio. Conservar el número en cada recipiente.',due:due(2,16),status:'pending'}].map((o,i)=>({...o,id:crypto.randomUUID(),number:23+i,createdAt:now.toISOString(),...(o.status==='ready'?{readyAt:now.toISOString()}:{})}));view='board';filter='all';$('#search').value='';render();}
$('#demo-button').onclick=()=>{if(demo){demo=false;render();}else startDemo();};$('#leave-demo').onclick=()=>{demo=false;render();};
$('#export-button').onclick=()=>{if(!current().length){toast('Todavía no hay pedidos para exportar.');return;}const blob=new Blob([toCSV(current())],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`turnocafe-${demo?'ejemplo-':''}${dateInput(new Date())}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV exportado con todos los pedidos y el historial.');};
function tvMode(on){$('#tv-screen').hidden=!on;$('.app').inert=on;$('.sidebar').inert=on;if(on){$('#exit-tv').focus();}else{$('#tv-button').focus();}}$('#tv-nav').onclick=()=>tvMode(true);$('#tv-button').onclick=()=>tvMode(true);$('#exit-tv').onclick=()=>tvMode(false);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#tv-screen').hidden)tvMode(false);});
$('#help-button').onclick=()=>$('#help-dialog').showModal();$('#help-close').onclick=()=>$('#help-dialog').close();
function stopVoice(){if(recognition){recognition.stop();recognition=null;}$('#dictate').textContent='♩ Dictar';}
$('#dictate').onclick=()=>{if(recognition){stopVoice();return;}const API=window.SpeechRecognition||window.webkitSpeechRecognition;if(!API){$('#voice-status').textContent='Este navegador no ofrece dictado compatible. Puedes escribir el pedido o probar un navegador con reconocimiento de voz.';return;}const r=new API();recognition=r;r.lang='es-EC';r.interimResults=true;r.continuous=false;$('#dictate').textContent='■ Detener';$('#voice-status').textContent='Escuchando… Habla cerca del micrófono. El navegador puede procesar el audio en su servicio de voz.';$('#transcript-container').hidden=false;let finalText='';r.onresult=e=>{let text='';for(let i=0;i<e.results.length;i++)text+=e.results[i][0].transcript+' ';$('#transcript').value=text.trim();finalText=text.trim();};r.onerror=e=>{$('#voice-status').textContent=e.error==='not-allowed'?'No se autorizó el micrófono. Puedes escribir el pedido.':e.error==='no-speech'?'No se detectó voz. Acerca el micrófono y vuelve a intentarlo.':'El dictado no pudo completarse. Revisa la conexión o escribe el pedido.';};r.onend=()=>{recognition=null;$('#dictate').textContent='♩ Dictar';if(finalText){$('#instructions').value=[$('#instructions').value.trim(),finalText].filter(Boolean).join('\n');$('#voice-status').textContent='Dictado añadido a las instrucciones. Revisa el cliente, peso, servicios, empaque y retiro antes de guardar.';}};try{r.start();}catch{recognition=null;$('#dictate').textContent='♩ Dictar';$('#voice-status').textContent='No se pudo iniciar el micrófono. Puedes escribir los datos.';}};
window.addEventListener('storage',e=>{if(e.key!==STORAGE_KEY&&e.key!==null)return;try{const data=JSON.parse(e.newValue||'[]');if(!validOrders(data))throw Error();orders=data;render();}catch{toast('No se pudo leer una actualización del cuaderno. Exporta una copia de tus datos.');}});
let alerted=new Set();function clock(){const now=new Date();$('#today').textContent=now.toLocaleDateString('es-EC',{weekday:'long',day:'numeric',month:'long'});$('#tv-clock').textContent=now.toLocaleTimeString('es-EC',{hour:'2-digit',minute:'2-digit',hour12:false});}setInterval(clock,1000);setInterval(()=>{render();if(demo)return;const needs=orders.filter(o=>o.status!=='delivered'&&new Date(o.due)-new Date()<3600000&&!alerted.has(o.id+o.due+o.status));if(needs.length){needs.forEach(o=>alerted.add(o.id+o.due+o.status));toast(`${needs.length} pedido(s) con retiro próximo o vencido. Revisa la pantalla de pendientes.`);}},60000);clock();render();if(storageBlocked)toast('No se pudo leer el almacenamiento. No registraremos cambios hasta que lo revises.');
